mapper.update:
update mngr_rqst
rqst_login_id = #{rqstLoginId}, rqst_mngr_nm = #{rqstMngrNm}, rqst_duty_cd = #{rqstDutyCd}, rqst_stts_cd = #{rqstSttsCd}, rjct_rsn_cn = #{rjctRsnCn}, rmrk_cn = #{rmrkCn}, apt_cmplex_no = #{aptCmplexNo}, rqst_no = #{rqstNo}
where rqst_no = #{rqstNo}

update mngr_rqst
   set rqst_stts_cd = 'reject',
       aprv_dt = sysdate,
       aprv_id = #{aprvId},
       rjct_rsn_cn = #{rjctRsnCn}
 where rqst_no = #{rqstNo}
